<?php
declare(strict_types=1);
namespace App\Controllers\Admin;
use App\Core\{AppKernel,Request,Response};
use App\Domain\Returns\ReturnRules as Rules;
final class ReturnsController extends AdminController {
 private function branches(int$id,string$permission):?array{return AppKernel::access()->accessibleBranchIdsForPermission($id,$permission);}
 private function intersect(?array$a,?array$b):?array{if($a===null)return$b;if($b===null)return$a;return array_values(array_intersect($a,$b));}
 private function allowed(int$id,string$returnPermission,string$type):?array{return$this->intersect($this->branches($id,'returns.'.$returnPermission),$this->branches($id,$type==='customer'?'deliveries.view':'purchases.view'));}
 private function scope(int$id,string$permission='view'):array{return['customer'=>$this->allowed($id,$permission,'customer'),'supplier'=>$this->allowed($id,$permission,'supplier')];}
 private function none(array$scope):bool{return$scope['customer']===[]&&$scope['supplier']===[];}
 private function union(array$scope):?array{if($scope['customer']===null||$scope['supplier']===null)return null;return array_values(array_unique(array_merge($scope['customer'],$scope['supplier'])));}
 private function missing(object$u):Response{return$this->adminView('admin/error',['title'=>'Devolución no disponible','message'=>'El documento no existe o está fuera de tu alcance.','user'=>$u],404);}
 private function date(string$value):?string{$value=trim($value);if($value==='')return null;$d=\DateTimeImmutable::createFromFormat('!Y-m-d',$value);if(!$d||$d->format('Y-m-d')!==$value)throw new \InvalidArgumentException('La fecha no es válida.');return$value;}
 public function index(Request$r):Response{$u=$this->requireUser();if($u instanceof Response)return$u;$scope=$this->scope($u->id);if($this->none($scope))return$this->requirePermission($u,'returns.view')??Response::redirect('/admin');$q=trim($r->query('q'));$status=$r->query('status');$type=$r->query('type');if($status!==''&&!isset(Rules::STATUSES[$status]))throw new \InvalidArgumentException('Estado inválido.');if($type!==''&&!isset(Rules::TYPES[$type]))throw new \InvalidArgumentException('Tipo inválido.');$branch=$r->integer('branch_id')?:null;$union=$this->union($scope);if($branch&&$union!==null&&!in_array($branch,$union,true))return$this->requirePermission($u,'returns.view',$branch)??Response::redirect('/admin');$from=$this->date($r->query('from'));$until=$this->date($r->query('until'));return$this->adminView('admin/returns/index',['title'=>'Devoluciones','activeNav'=>'returns','user'=>$u,'page'=>AppKernel::returns()->listing($q,$status,$type,$branch,$from,$until,$scope,max(0,(int)$r->query('offset','0'))),'q'=>$q,'status'=>$status,'type'=>$type,'branchId'=>$branch,'from'=>$from,'until'=>$until,'branches'=>array_values(array_filter(AppKernel::returns()->branches(),fn($b)=>$union===null||in_array((int)$b['id'],$union,true))),'canCreate'=>!$this->none($this->scope($u->id,'create'))]);}
 public function createForm(Request$r,array$values=[],?string$error=null):Response{$u=$this->requireUser();if($u instanceof Response)return$u;$type=$values['return_type']??$r->query('type','customer');if(!isset(Rules::TYPES[$type]))$type='customer';$allowed=$this->allowed($u->id,'create',$type);if($allowed===[])return$this->requirePermission($u,'returns.create')??Response::redirect('/admin');$sourceId=(int)($values['source_id']??$r->query('source_id','0'));$source=$sourceId?AppKernel::returns()->source($type,$sourceId,$allowed):null;if($sourceId&&!$source)return$this->missing($u);$items=$source?AppKernel::returns()->sourceItems($type,$sourceId):[];foreach($items as&$item){$item['committed']=AppKernel::returns()->committed($type,(int)$item['source_item_id']);$item['available']=\App\Domain\Pricing\Decimal::parse($item['original_quantity'],6)->subtract(\App\Domain\Pricing\Decimal::parse($item['committed'],6))->format(6);}unset($item);$q=$r->query('q');return$this->adminView('admin/returns/create',['title'=>'Registrar devolución','activeNav'=>'returns','user'=>$u,'error'=>$error,'values'=>$values?:['return_type'=>$type,'source_id'=>$sourceId,'operation_key'=>bin2hex(random_bytes(20))],'type'=>$type,'source'=>$source,'items'=>$items,'q'=>$q,'options'=>$source?null:AppKernel::returns()->sourceOptions($type,$q,$allowed,max(0,(int)$r->query('offset','0')))],$error?422:200);}
 public function create(Request$r):Response{$u=$this->requireUser();if($u instanceof Response)return$u;if($e=$this->requireCsrf($r,$u))return$e;$type=$r->input('return_type');$allowed=isset(Rules::TYPES[$type])?$this->allowed($u->id,'create',$type):[];if($allowed===[])return$this->requirePermission($u,'returns.create')??Response::redirect('/admin');$input=['return_type'=>$type,'source_id'=>$r->input('source_id'),'operation_key'=>$r->input('operation_key'),'reason'=>$r->input('reason')];try{$id=AppKernel::returnManagement()->create($input,$r->keyedValues('quantity'),$r->keyedValues('condition'),$allowed,$u->id,fn($id,$b,$a)=>AppKernel::audit()->record($u->id,'return.'.$a,'operational_return',$id,$b,'success'));return Response::redirect('/admin/returns/detail?id='.$id);}catch(\InvalidArgumentException|\App\Application\Exceptions\ApplicationException$e){$error=$e->getMessage();}catch(\Throwable){$error='No se pudo registrar la devolución. No se confirmaron cambios.';}$input['quantities']=$r->keyedValues('quantity');$input['conditions']=$r->keyedValues('condition');return$this->createForm($r,$input,$error);}
 public function detail(Request$r):Response{$u=$this->requireUser();if($u instanceof Response)return$u;$scope=$this->scope($u->id);if($this->none($scope))return$this->requirePermission($u,'returns.view')??Response::redirect('/admin');$return=AppKernel::returns()->find($r->integer('id'),$scope);if(!$return)return$this->missing($u);$branch=(int)$return['branch_id'];$sourcePermission=$return['return_type']==='customer'?'deliveries.view':'purchases.view';if($e=$this->requirePermission($u,$sourcePermission,$branch))return$e;$actions=['authorize'=>AppKernel::access()->hasPermission($u->id,'returns.authorize',$branch),'reject'=>AppKernel::access()->hasPermission($u->id,'returns.authorize',$branch),'receive'=>AppKernel::access()->hasPermission($u->id,'returns.receive',$branch),'dispatch'=>AppKernel::access()->hasPermission($u->id,'returns.dispatch',$branch),'cancel'=>AppKernel::access()->hasPermission($u->id,'returns.cancel',$branch)];$history=AppKernel::access()->hasPermission($u->id,'returns.history',$branch)?AppKernel::returns()->history((int)$return['id']):[];return$this->adminView('admin/returns/detail',['title'=>$return['folio'],'activeNav'=>'returns','user'=>$u,'return'=>$return,'items'=>AppKernel::returns()->items((int)$return['id']),'history'=>$history,'actions'=>$actions,'selectedAction'=>$r->query('action')]);}
 public function action(Request$r):Response{$u=$this->requireUser();if($u instanceof Response)return$u;if($e=$this->requireCsrf($r,$u))return$e;$action=$r->input('action');$permission=match($action){'authorize','reject'=>'authorize','receive'=>'receive','dispatch'=>'dispatch','cancel'=>'cancel',default=>''};if($permission==='')return$this->missing($u);$scope=$this->scope($u->id,$permission);if($this->none($scope))return$this->requirePermission($u,'returns.'.$permission)??Response::redirect('/admin');$id=$r->integer('id');$return=AppKernel::returns()->find($id,$scope);if(!$return)return$this->missing($u);$branch=(int)$return['branch_id'];$sourcePermission=$return['return_type']==='customer'?'deliveries.view':'purchases.view';if($e=$this->requirePermission($u,$sourcePermission,$branch))return$e;if(in_array($action,['receive','dispatch','cancel'],true)&&$r->input('physical_confirmation')!=='1')return$this->run(fn()=>throw new \InvalidArgumentException('Confirma explícitamente la operación.'),'','/admin/returns/detail?id='.$id);return$this->run(fn()=>AppKernel::returnManagement()->action($id,(int)$r->input('lock_version'),$action,$r->input('operation_key'),$r->input('notes'),$scope,$u->id,fn($id,$b,$a)=>AppKernel::audit()->record($u->id,'return.'.$a,'operational_return',$id,$b,'success')),'Operación confirmada.','/admin/returns/detail?id='.$id,$u->id,'return.'.$action,'operational_return',$id,$branch);}
}
